#' RD Density (Manipulation) Test
#'
#' 
#' @param data .
#' @param running .
#' @param cutVar .
#' @param cutoff .
#' @param p .
#' @param q .
#' @param kernel .
#' @param fitselect .
#' @param vce .
#' @param hManual .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$test} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$sample} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$densPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$test$asDF}
#'
#' \code{as.data.frame(results$test)}
#'
#' @export
rddens <- function(
    data,
    running,
    cutVar,
    cutoff = 0,
    p = 2,
    q = 0,
    kernel = "triangular",
    fitselect = "unrestricted",
    vce = "jackknife",
    hManual = 0,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("rddens requires jmvcore to be installed (restart may be required)")

    if ( ! missing(running)) running <- jmvcore::resolveQuo(jmvcore::enquo(running))
    if ( ! missing(cutVar)) cutVar <- jmvcore::resolveQuo(jmvcore::enquo(cutVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(running), running, NULL),
            `if`( ! missing(cutVar), cutVar, NULL))


    options <- rddensOptions$new(
        running = running,
        cutVar = cutVar,
        cutoff = cutoff,
        p = p,
        q = q,
        kernel = kernel,
        fitselect = fitselect,
        vce = vce,
        hManual = hManual,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- rddensClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

